{
  "name": "builder_all_pairs_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap so constructed preferences are more consistent and less noisy, improving training signal quality and generalization.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Only keep preferences with a minimum objective gap (lower is better).\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_threshold', 'gap_threshold': float(gap_threshold)})\n"
}

{
  "name": "builder_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap between winner and loser; this reduces noisy/ambiguous preferences and focuses training on clearer signal while keeping all qualifying pairs.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Lower objective is better. Keep only pairs with a sufficient gap to avoid near-ties.\n    gap_threshold = extra.get('gap_threshold', 0.0) if extra is not None else 0.0\n    obj_i = objective[:, :, None]\n    obj_j = objective[:, None, :]\n    gap = obj_j - obj_i\n    mask = (obj_i < obj_j) & (gap >= gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_threshold', 'gap_threshold': float(gap_threshold)})\n"
}

{
  "name": "loss_logsigmoid_consensus_costshift",
  "intuition": "All parents implement the same stable core: a pairwise preference objective using -logsigmoid(alpha*scale*(log_prob_w-log_prob_l)) with tight clamping for numerical stability and optional per-example weighting. A consistent variant also shifts the logit by a small detached cost gap, which preserves the preference-gradient structure while incorporating external cost information without backpropagating through the costs. This child keeps the consensus core, uses a mid-range scale close to the parent cluster, and includes the detached cost shift only when cost fields are present, maintaining robustness across batch schemas.",
  "pseudocode": "d = log_prob_w - log_prob_l\nshift = -cost_coef*detach(cost_b - cost_a) if costs available else 0\nx = clamp(alpha*scale*d + shift, -20, 20)\nloss = -logsigmoid(x)\nloss = loss*weight if provided\nreturn mean(loss)",
  "hyperparams": {
    "scale": 0.92,
    "cost_coef": 0.1,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "batch_optional": [
        "weight",
        "cost_a",
        "cost_b"
      ],
      "extra": [
        "alpha",
        "hyperparams"
      ]
    }
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 0.92))\n    cost_coef = float(hp.get('cost_coef', 0.1))\n    cmin = float(hp.get('clamp_min', -20.0))\n    cmax = float(hp.get('clamp_max', 20.0))\n\n    x = alpha * scale * (lpw - lpl)\n\n    # Optional detached cost-based shift (only if provided in the batch)\n    if ('cost_a' in batch) and ('cost_b' in batch):\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n        x = x - cost_coef * gap\n\n    x = ops.clamp(x, cmin, cmax)\n    loss = -ops.logsigmoid(x)\n\n    weight = batch.get('weight', None)\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss on log-probability differences with clamped logits for numerical stability; optional detached cost shift adds an exogenous margin term without altering gradients through the cost features."
}

