  ],
  "expects": {
    "log_prob_w": "Tensor",
    "log_prob_l": "Tensor",
    "weight": "Optional[Tensor]"
  },
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']

    hyper = extra.get('hyperparams', {}) if extra is not None else {}
    scale = float(hyper.get('scale', 1.0))
    cmin = float(hyper.get('clamp_min', -20.0))
    cmax = float(hyper.get('clamp_max', 20.0))

    margin = scale * (lpw - lpl)
    margin = ops.clamp(margin, cmin, cmax)
    loss = -ops.logsigmoid(margin)

    weight = batch.get('weight', None)
